function create_risks_excel(db_name, project_id):
    # Извлекает риски из БД
    risks = db.query('SELECT * FROM risks WHERE project_id = ? ORDER BY priority DESC', [project_id])
    # Формирует Excel с листом Risks и сводкой по приоритетам
    return file_creator.createExcelFromDb(db_name, 'risks', {
        'Risks': risks,
        'Summary': {
            'high': count(risks, 'priority', 'high'),
            'medium': count(risks, 'priority', 'medium'),
            'low': count(risks, 'priority', 'low')
        }
    })
